with session_summary as (select session_id, avg(duration_sec) as avg_duration_sec, max(duration_sec) as max_duration_sec from web_events where to_date(event_time) < '2024-04-07' group by session_id) select sessions.id, sessions.device, sessions.started_at, session_summary.avg_duration_sec, session_summary.max_duration_sec from sessions left join session_summary on sessions.id = session_summary.session_id;
